const tr = value => window.businessI18n.text(value);
const root=document.querySelector('#app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(cents,currency='USD')=>new Intl.NumberFormat(window.businessI18n.locale,{style:'currency',currency}).format(Number(cents||0)/100);
const day=value=>value?new Date(value*1000).toLocaleDateString(window.businessI18n.locale): '—';
let supplierId='',contexts=[],supplierRole='OWNER';
function storedWorkspace(){try{return localStorage.getItem('autolink_supplier_workspace');}catch{return null;}}
function rememberWorkspace(id){try{localStorage.setItem('autolink_supplier_workspace',id);}catch{}}
const api=async(path,method='GET',body,timeoutMs=15000)=>{
  let r;const current=navigationId;
  const signal=method==='GET'&&readController?AbortSignal.any([readController.signal,AbortSignal.timeout(timeoutMs)]):AbortSignal.timeout(timeoutMs);
  try {r=await fetch(path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(supplierId&&path.startsWith('/autolink/supplier/')?{'X-Autolink-Supplier':supplierId}:{})},body:body===undefined?undefined:JSON.stringify(body),signal});const p=await r.json();if(method==='GET'&&current!==navigationId)throw new DOMException('Navigation changed','AbortError');if(!r.ok||p.code!==200)throw Object.assign(Error(typeof p?.msg==='string'?p.msg:'Request failed.'),{status:r.ok?Number(p?.code):r.status});return p.data;
  } catch(error) { throw window.businessI18n.apiError?.(error,r?.status) || error; }
};
const link=(href,label,secondary=false)=>`<a class="button-link${secondary?' secondary':''}" href="${esc(href)}">${esc(tr(label))}</a>`;
const empty=(title,detail,action='')=>`<div class="empty"><strong>${esc(title)}</strong><p>${esc(detail)}</p>${action}</div>`;
const panel=(title,content)=>`<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2></div>${content}</section>`;
const title=(name,description,action='')=>`<div class="page-top"><div><span class="eyebrow">${esc(tr("AUTOLINK · SUPPLIER CENTER"))}</span><h1>${esc(name)}</h1><p>${esc(description)}</p></div>${action}</div>`;
let me=null,application=null,catalog=[],route='',verificationDocuments=[];
let navigationId=0,readController;
function assertSupplierNavigation(current){if(current!==navigationId)throw new DOMException("Navigation changed","AbortError");}
function layout(content){
  const groups=[['Dashboard',[['','Dashboard'],['notifications','Notifications']]],['Business activity',[['vehicles','Vehicles'],['listing-service','Listing service'],['inquiries','Inquiries'],['buying-requests','Buying requests'],['quotes','Quotes'],['buyers','Buyers / CRM'],['analytics','Analytics']]],['Company verification',[['application','Verification'],['profile','Company profile'],['team','Team'],['settings','Account & Security']]]];
  const nav=groups.map(([heading,items])=>{const allowed=items.filter(([slug])=>supplierRole==='OWNER'||!['application','profile','vehicles','buying-requests'].includes(slug));return allowed.length?`<div class="seller-nav-group"><div class="seller-nav-label">${esc(tr(heading))}</div>${allowed.map(([slug,label])=>`<a href="/supplier${slug?'/'+slug:''}" class="${route===slug?'active':''}" ${route===slug?'aria-current="page"':''}>${esc(tr(label))}</a>`).join('')}</div>`:'';}).join('');
  root.innerHTML=`<header class="site-head"><div class="site-head-inner"><a class="brand" href="/">AUTOLINK<i>▪</i></a><span class="seller-head-label">${esc(tr('SUPPLIER CENTER'))}</span><div class="head-right">${window.businessI18n.languageControl()}<label class="field">${esc(tr('Workspace'))}<select id="supplier-workspace">${contexts.map(c=>`<option value="${esc(c.supplier_id)}" ${c.supplier_id===supplierId?'selected':''}>${esc(c.company_name||tr('My application'))} · ${esc(tr(c.role))}</option>`).join('')}</select></label><a href="/buyer">${esc(tr("Go to Buyer Center"))}</a><a href="/trade/vehicles">${esc(tr('Website'))}</a></div></div></header><div class="workspace supplier-layout"><aside class="side" id="buyer-sidebar"><div class="side-title">${esc(tr('SUPPLIER CENTER'))}</div>${nav}<div class="side-bottom"><a href="/trade/vehicles">${esc(tr('Public website'))}</a><button data-action="logout">${esc(tr('Sign out'))}</button></div></aside><main class="content"><button class="btn secondary mobile-menu" data-action="menu">${esc(tr('☰ Menu'))}</button><div id="supplier-content">${me?.isTestWorkspace?`<div class="supplier-profile-note" role="status"><strong>${esc(tr("Test workspace"))}</strong><br>${esc(tr("Private testing only. Create vehicle drafts; public listings, real buyer contact and agreement signing are disabled."))}</div>`:""}${content}</div></main></div>`;
}
function note(message,error=false){const host=document.querySelector('#supplier-content');if(!host)return;host.querySelector('.supplier-alert')?.remove();host.insertAdjacentHTML('afterbegin',`<div class="alert ${error?'error':''} supplier-alert" role="status">${esc(tr(message))}</div>`);}
function guard(){
  if(!me){
    const invited=route==='team';
    const destination=encodeURIComponent(location.pathname+location.search);
    layout(title(tr('Sign in required'),tr(invited?'Register and verify the invited email before accepting.':'Use your business account to access the Supplier Center.'))+
      link(invited?'/buyer/login?returnTo='+destination:'/merchant/login?returnTo=%2Fsupplier',tr('Sign in'))+
      (invited?' '+link('/buyer/register?returnTo='+destination,tr('Register'),true):''));
    return false;
  }
  if(!(me.capabilities?.supplier??['BUYER','MERCHANT','SUPPLIER'].includes(me.role))){layout(title(tr('Supplier access required'),tr('This account does not have a supplier role.'))+link('/buyer',tr('Go to Buyer Center'),true));return false;}
  return true;
}
function reviewNotice(){if(me?.isTestWorkspace)return `<p class="notice">${esc(tr('This test workspace is not a verified business.'))}</p>`;const status=application?.status||'DRAFT';return `<div class="supplier-profile-note"><strong>${esc(status==='APPROVED'?onboardingText(2):tr('Company application'))}: ${esc(tr(status))}</strong><br>${esc(tr(status==='APPROVED'?'Your company may submit vehicles for platform review. Vehicle listings appear publicly only after their own approval.':status==='PENDING'?onboardingText(5):'Complete the company application before publishing vehicles.'))}${application?.review_reason?`<br>${esc(tr("Review note:"))} ${esc(application.review_reason)}`:''}</div>`;}
const statusLabel=status=>({PENDING_REVIEW:'Pending review',APPROVED:'Approved',ONLINE:'Online',OFFLINE:'Offline',SOLD_OUT:'Sold out',ARCHIVED:'Archived',REJECTED:'Rejected',DRAFT:'Draft'}[status]||status);
function summaryCards(entries){return `<div class="supplier-summary">${entries.map(([label,count])=>`<article class="card"><small>${esc(tr(label))}</small><strong>${esc(new Intl.NumberFormat(window.businessI18n.locale).format(count))}</strong></article>`).join('')}</div>`;}
function reportScope(data){return `<p class="notice">${esc(tr(data.scope==='ASSIGNED'?'Statistics for your assigned buyers only.':'Company-wide statistics'))} ${esc(tr('Counts include all matching records, not just the current list page.'))}</p>`;}
function statusSummary(label,counts,vehicle=false){return panel(tr(label),`<div class="supplier-data">${Object.entries(counts).map(([status,count])=>`<div><span>${esc(tr(vehicle?statusLabel(status):status))}</span><strong>${esc(new Intl.NumberFormat(window.businessI18n.locale).format(count))}</strong></div>`).join('')}</div>`);}
async function dashboard(){const current=navigationId;
  const approved=application?.status==='APPROVED';
  const data=approved?await api('/autolink/supplier/overview'):{scope:'COMPANY',counts:{vehicles:0,pendingVehicleReviews:0,inquiries:0,sentQuotes:0},recentInquiries:[]};assertSupplierNavigation(current);
  const c=data.counts,assigned=data.scope==='ASSIGNED';
  const entries=assigned?[['Buyer inquiries',c.inquiries],['Open inquiries',c.activeInquiries],['Buyer relationships',c.buyers],['Quotations sent',c.sentQuotes]]:[['Vehicles',c.vehicles],['Pending vehicle reviews',c.pendingVehicleReviews],['Buyer inquiries',c.inquiries],['Quotations sent',c.sentQuotes]];
  const tasks=approved?[
    ['/supplier/inquiries','Open inquiries',c.activeInquiries||0],
    ['/supplier/quotes','Draft',data.quoteStatuses?.DRAFT||0],
    ...(!assigned?[['/supplier/vehicles','Pending vehicle reviews',c.pendingVehicleReviews||0],['/supplier/vehicles','Rejected',data.vehicleStatuses?.REJECTED||0]]:[])
  ]:[['/supplier/application','Complete company verification',1]];
  const next=!approved?link('/supplier/application',tr('Complete company verification')):assigned||c.vehicles?link('/supplier/inquiries',tr('Review inquiries'),true):link('/supplier/vehicles/new',tr('Add your first vehicle'));
  layout(title(tr('Dashboard'),tr('Manage company verification, vehicle listings, buyer inquiries and quotations.'),supplierRole==='OWNER'&&approved?link('/supplier/vehicles/new',tr('Add vehicle')):'')+summaryCards(entries)+`<div class="seller-task-strip">${tasks.map(([href,label,count])=>`<a href="${esc(href)}"><span>${esc(tr(label))}</span><strong>${Number(count)}</strong><span aria-hidden="true">›</span></a>`).join('')}</div><div class="two-cols">${panel(tr('Recent inquiries'),data.recentInquiries.length?`<div class="list">${data.recentInquiries.map(inquiryRow).join('')}</div>`:empty(tr('No inquiries yet'),tr('Buyer inquiries for your approved listings appear here.')))}<div>${panel(tr('Next steps'),`<div class="seller-shortcuts">${next}${approved?link('/supplier/analytics',tr('Analytics'),true):''}${supplierRole==='OWNER'&&approved?link('/supplier/profile',tr('Company profile'),true):''}</div>`)}${panel(tr('Company application'),`<span class="seller-status" data-status="${esc(application?.status||'DRAFT')}">${esc(tr(me?.isTestWorkspace?'Test workspace':application?.status||'DRAFT'))}</span><p class="notice">${esc(tr('Merchants set their own prices. AUTOLINK reviews listings before publication.'))}</p>${link('/supplier/application',tr('Details'),true)}`)}</div></div>`+(approved?reportScope(data):'')+`<p class="notice">${esc(tr('Buyer and supplier settle vehicle transactions directly. AUTOLINK does not hold vehicle purchase funds or guarantee a deal.'))}</p>`);
}
async function analytics(){const current=navigationId;
  const data=await api('/autolink/supplier/overview'),c=data.counts,p=data.period;assertSupplierNavigation(current);
  layout(title(tr('Analytics'),tr('Business activity'),link(location.pathname+location.search,tr('Refresh'),true))+reportScope(data)+summaryCards([['Buyer inquiries',c.inquiries],['Open inquiries',c.activeInquiries],['Quotations sent',c.sentQuotes],['Acceptance intentions',c.acceptedIntents]])+panel(tr('Last 30 days'),`<p class="notice">${esc(tr('Reporting period'))}: ${esc(day(p.from))} · ${esc(day(p.until))}</p>`+summaryCards([['Inquiries received',p.inquiriesReceived],['Quotations sent',p.quotesSent],['Follow-up notes',p.followUpNotes]]))+`<div class="two-cols">${statusSummary('Inquiry status',data.inquiryStatuses)}${statusSummary('Quotation status',data.quoteStatuses)}${statusSummary('Customer status',data.customerStatuses)}${data.vehicleStatuses?statusSummary('Vehicle status',data.vehicleStatuses,true):''}</div><p class="notice">${esc(tr('Quotation acceptance records buyer intent, not a completed trade or payment.'))}</p><p class="notice">${esc(tr('CRM stages are set by your team and do not confirm a vehicle transaction.'))}</p><p class="muted">${esc(tr('Updated'))}: ${esc(day(data.generatedAt))}</p>`);
}
const onboardingLabels={"en":["New supplier onboarding is not open: the final agreement and operator details are not ready. You can save a company draft.","Enable supplier account","Business account active","Complete company details, upload the required evidence, confirm the final agreement, then submit to enable your business account. Vehicle listings need separate review.","An active business account is not a platform guarantee of company credentials, stock or fulfilment.","Legacy application: submit explicitly after confirming the final agreement to enable the account."],"zh":["新的商家入驻暂未开放：正式协议与运营资料尚未就绪。可以保存企业资料草稿。","启用供应商账号","平台业务账号已启用","填写完整企业资料、上传所需材料、确认正式协议，再提交启用业务账号。车源仍需单独审核。","业务账号已启用不代表平台保证企业资质、库存或履约。","历史申请：确认正式协议后，请主动提交以启用账号。"],"ar":["تسجيل الموردين الجدد غير متاح: الاتفاقية النهائية وبيانات المشغل غير جاهزة. يمكنك حفظ مسودة بيانات الشركة.","تفعيل حساب المورد","حساب الأعمال مفعّل","أكمل بيانات الشركة وارفع الأدلة المطلوبة وأكد الاتفاقية النهائية، ثم أرسل لتفعيل حساب الأعمال. تحتاج المركبات إلى مراجعة مستقلة.","تفعيل حساب الأعمال لا يضمن مؤهلات الشركة أو المخزون أو تنفيذ الالتزامات.","طلب سابق: أكد الاتفاقية النهائية ثم أرسل الطلب صراحة لتفعيل الحساب."],"ru":["Регистрация новых поставщиков недоступна: окончательное соглашение и данные оператора не готовы. Можно сохранить черновик компании.","Активировать аккаунт поставщика","Бизнес-аккаунт активен","Заполните данные компании, загрузите документы, подтвердите окончательное соглашение и отправьте заявку для активации. Автомобили проходят отдельную проверку.","Активный бизнес-аккаунт не гарантирует документы компании, запасы или исполнение обязательств.","Старая заявка: подтвердите окончательное соглашение и отправьте заявку для активации."],"kk":["Жаңа жеткізушілерді тіркеу ашылмаған: соңғы келісім мен оператор деректері дайын емес. Компания жобасын сақтауға болады.","Жеткізуші аккаунтын іске қосу","Бизнес аккаунты іске қосылған","Компания деректерін толтырып, құжаттарды жүктеңіз, соңғы келісімді растаңыз және аккаунтты іске қосу үшін жіберіңіз. Көліктер бөлек тексеріледі.","Іске қосылған бизнес аккаунты компания құжаттарына, қорға немесе міндеттемелерге кепілдік бермейді.","Бұрынғы өтінім: соңғы келісімді растап, аккаунтты іске қосу үшін өтінімді жіберіңіз."],"uz":["Yangi yetkazib beruvchilar uchun ro‘yxatdan o‘tish ochilmagan: yakuniy kelishuv va operator ma’lumotlari tayyor emas. Kompaniya qoralamasini saqlashingiz mumkin.","Yetkazib beruvchi hisobini faollashtirish","Biznes hisobi faol","Kompaniya ma’lumotlarini to‘ldiring, dalillarni yuklang, yakuniy kelishuvni tasdiqlang va hisobni faollashtirish uchun yuboring. Avtomobillar alohida tekshiriladi.","Faol biznes hisobi kompaniya hujjatlari, zaxira yoki majburiyatlar bajarilishiga kafolat bermaydi.","Oldingi ariza: yakuniy kelishuvni tasdiqlab, hisobni faollashtirish uchun arizani yuboring."],"ko":["신규 공급업체 가입은 아직 열리지 않았습니다. 최종 약관과 운영자 정보가 준비되지 않았습니다. 회사 정보 초안을 저장할 수 있습니다.","공급업체 계정 활성화","사업 계정 활성화됨","회사 정보를 작성하고 필수 증빙을 업로드한 후 최종 약관에 동의하고 제출하여 사업 계정을 활성화하세요. 차량은 별도 심사가 필요합니다.","사업 계정 활성화는 회사 자격, 재고 또는 이행을 보증하지 않습니다.","기존 신청: 최종 약관에 동의한 후 직접 제출하여 계정을 활성화하세요."],"fr":["Les nouvelles inscriptions fournisseurs ne sont pas ouvertes : l’accord définitif et les données de l’opérateur ne sont pas prêts. Vous pouvez enregistrer un brouillon.","Activer le compte fournisseur","Compte professionnel actif","Complétez les informations, importez les justificatifs, confirmez l’accord définitif et soumettez pour activer le compte. Les véhicules nécessitent un examen distinct.","Un compte professionnel actif ne garantit ni les justificatifs de l’entreprise, ni le stock, ni l’exécution.","Ancienne demande : confirmez l’accord définitif puis soumettez pour activer le compte."],"sw":["Usajili wa wasambazaji wapya haujafunguliwa: makubaliano ya mwisho na taarifa za mwendeshaji hazijawa tayari. Unaweza kuhifadhi rasimu ya kampuni.","Washa akaunti ya msambazaji","Akaunti ya biashara imewashwa","Jaza taarifa za kampuni, pakia ushahidi, thibitisha makubaliano ya mwisho kisha tuma kuwasha akaunti. Magari yanahitaji ukaguzi tofauti.","Akaunti ya biashara haihakikishi nyaraka za kampuni, hisa au utekelezaji.","Ombi la zamani: thibitisha makubaliano ya mwisho kisha tuma ombi kuwasha akaunti."]};
