function documentRecords(docs){return `<div class="seller-evidence-checklist">${[["BUSINESS_LICENSE","Business license"],["PREMISES_PHOTO","Operating premises photo"],["INVENTORY_PHOTO","Inventory photo"]].map(([kind,label])=>`<div><span>${esc(tr(label))}</span><small>${esc(tr(docs.some(d=>d.kind===kind)?"Uploaded":"Required"))}</small></div>`).join('')}</div>${docs.some(d=>['PREMISES_PHOTO','INVENTORY_PHOTO'].includes(d.kind))?`<div class="seller-evidence-photos">${docs.filter(d=>['PREMISES_PHOTO','INVENTORY_PHOTO'].includes(d.kind)).map(d=>`<figure><img src="/autolink/supplier/documents/${encodeURIComponent(d.id)}" alt="${esc(tr(d.kind==='PREMISES_PHOTO'?'Operating premises photo':'Inventory photo'))}"><figcaption>${esc(tr(d.kind==='PREMISES_PHOTO'?'Operating premises photo':'Inventory photo'))}</figcaption></figure>`).join('')}</div>`:''}${docs.length?`<div class="list">${docs.map(d=>`<div class="supplier-row"><div class="supplier-row-main"><strong>${esc(d.filename)}</strong><small>${esc(tr({BUSINESS_LICENSE:'Business license',EXPORT_LICENSE:'Export license',OTHER:'Other company document',PREMISES_PHOTO:'Operating premises photo',INVENTORY_PHOTO:'Inventory photo'}[d.kind]||d.kind))} · ${Math.ceil(d.bytes/1024)} ${esc(tr('KB'))}</small></div><div class="supplier-actions">${link('/autolink/supplier/documents/'+encodeURIComponent(d.id),tr('Download'),true)}${d.kind==='BUSINESS_LICENSE'&&!['PENDING','APPROVED','SUSPENDED'].includes(application?.status)?`<button class="btn secondary" type="button" data-action="read-license" data-id="${esc(d.id)}">${esc(tr('Read license details'))}</button>`:''}</div></div>`).join('')}</div>`:empty(tr('No documents uploaded'),tr('Business license is required before submitting your application.'))}`;}
async function recognizeUploadedLicense(file){
  const form=document.querySelector('#application-form'),host=document.querySelector('#license-recognition-status');
  if(!form||!host||host.dataset.busy==='yes')return;
  host.dataset.busy='yes';
  const replaceDefault=!application?.registration_no&&form.elements.companyName.value===form.elements.companyName.defaultValue;
  try{
    host.textContent=tr('Reading business license in your browser…');
    const engine=await import('/assets/license-ocr.mjs?v=20261007-upload-fix');
    const fields=await engine.recognizeLicense(file,progress=>{if(host.isConnected)host.textContent=tr('Reading business license in your browser…')+' '+Math.round(progress*100)+'%';});
    if(!form.isConnected||!host.isConnected)return;
    const applied=engine.applyLicenseFields(form,fields,replaceDefault);
    host.textContent=tr(applied.length?'License details filled in. Check them before saving; existing entries were kept.':'No additional details could be filled in. Please check and complete the form manually.');
    host.className='supplier-profile-note';
  }catch{
    if(host.isConnected)host.textContent=tr('The document is uploaded. Automatic reading failed; please enter the details manually.');
  }finally{host.dataset.busy='no';}
}
async function uploadVerificationDocument(form){
  const status=form.querySelector('#document-upload-status');
  const show=(message,error=false)=>{if(status){status.textContent=tr(message);status.className='notice wide'+(error?' error':'');}};
  try{
    const input=form.querySelector('[type=file]'),file=input.files[0];
    if(!file||file.size>5000000)throw Error(tr('Choose a PDF, PNG or JPEG of 5 MB or smaller.'));
    const mimeByExt={pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg'};
    const contentType=file.type||mimeByExt[file.name.split('.').pop().toLowerCase()];
    if(!Object.values(mimeByExt).includes(contentType))throw Error(tr('PDF, PNG or JPEG required.'));
    const kind=form.elements.kind.value;
    if(['PREMISES_PHOTO','INVENTORY_PHOTO'].includes(kind)&&contentType==='application/pdf')throw Error(tr('Operating premises and inventory evidence must be PNG or JPEG photos.'));
    show('Uploading… Please keep this page open.');
    const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error(tr('Cannot read this file. Please select it again.')));reader.readAsDataURL(file);});
    const saved=await api('/autolink/supplier/documents','POST',{kind,filename:file.name,contentType,base64},120000);
    if(!saved?.id)throw Error(tr('Upload could not be confirmed. Please reload before trying again.'));
    verificationDocuments=[saved,...verificationDocuments.filter(d=>d.id!==saved.id)];
    const recordsHost=document.querySelector('#verification-documents');
    if(recordsHost)recordsHost.innerHTML=documentRecords(verificationDocuments);
    const checklistHost=document.querySelector('#supplier-publication-checklist');
    if(checklistHost)checklistHost.outerHTML=publicationChecklist();
    input.value='';
    show('Document uploaded successfully. Your form entries have been kept.');
    if(kind==='BUSINESS_LICENSE')void recognizeUploadedLicense(file);
  }catch(error){
    show(error.message,true);
    status?.scrollIntoView({block:'nearest',behavior:'smooth'});
    throw error;
  }
}
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action="read-license"]');if(!button||button.disabled)return;
  button.disabled=true;
  try{
    const response=await fetch('/autolink/supplier/documents/'+encodeURIComponent(button.dataset.id),{credentials:'same-origin',headers:{'X-Autolink-Supplier':supplierId},signal:AbortSignal.timeout(60000)});
    if(!response.ok)throw Error();
    const blob=await response.blob();if(blob.size>5000000)throw Error();
    await recognizeUploadedLicense(new File([blob],blob.type==='application/pdf'?'license.pdf':'license-image',{type:blob.type}));
  }catch{
    const host=document.querySelector('#license-recognition-status');if(host)host.textContent=tr('The document is uploaded. Automatic reading failed; please enter the details manually.');
  }finally{button.disabled=false;}
});
